<template>
  <div class="flex flex-col gap-4">
    <ProjectDashboardNavigation
      :project-id="projectId"
      :params="params"
      :project-start-end-date="{ start: projectStartEndDate.start, end: projectStartEndDate.end }"
      :calculated-at="dashboardData?.calculated_at"
    />
    <AppLoader v-if="isLoadingDashboard" subject="dashboard" />
    <AppError v-else-if="dashboardError" title="Failed to load dashboard" :error="dashboardError" />
    <AppEmpty v-else-if="!dashboardData?.charts" subject="project charts" />
    <div v-else class="grid grid-cols-12 gap-4">
      <DashboardChartsCard
        :charts="dashboardData.charts"
        :params="params"
        :project-id="projectId"
        :map-date-range="{
          startDate: params.start_date ?? projectStartEndDate.start,
          endDate: params.end_date ?? projectStartEndDate.end,
        }"
        :query-key="['project.id.dashboard', projectId, params]"
        map-type="project"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import type { GetSignatureProjectDashboardData } from '~/client';
import { getSignatureProjectDashboard } from '~/client';

interface Props {
  projectId: string;
  projectStartEndDate: { start: string; end: string };
}

const props = defineProps<Props>();
const route = useRoute();

const params = computed(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );
  const urlParams: GetSignatureProjectDashboardData['query'] = {
    start_date: route.query.start_date ? route.query.start_date.toString() : props.projectStartEndDate.start,
    end_date: route.query.end_date ? route.query.end_date.toString() : props.projectStartEndDate.end,
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    regions: processArrayQueryParameterFromUrl(route.query.regions),
    subcontractor_company_ids,
    include_unassigned,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetSignatureProjectDashboardData['query'];
});

const {
  data: dashboardData,
  error: dashboardError,
  isLoading: isLoadingDashboard,
} = useQuery({
  key: () => ['project.id.dashboard', props.projectId, params.value],
  query: () =>
    getSignatureProjectDashboard({
      composable: '$fetch',
      path: { project_id: props.projectId },
      query: params,
    }),
  enabled: () => !!props.projectId,
});
</script>
